import csv
import datetime
import io
import aiosqlite
from fastapi import APIRouter
from fastapi.responses import JSONResponse, StreamingResponse

from .config import SearchRecConfig


def admin_router(config: SearchRecConfig) -> APIRouter:
    router = APIRouter(prefix="/api/admin", tags=["admin"])

    @router.get("/stats")
    async def stats():
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row

            row = await (await db.execute(
                "SELECT COUNT(*) as clicks, COUNT(DISTINCT session_id) as sessions FROM click_events"
            )).fetchone()
            total_clicks   = row["clicks"]
            total_sessions = row["sessions"]

            total_items = (await (await db.execute(
                "SELECT COUNT(*) as n FROM items"
            )).fetchone())["n"]

            items_with_recs = (await (await db.execute(
                "SELECT COUNT(DISTINCT item_id) as n FROM item_similarities"
            )).fetchone())["n"]

            sim_row = await (await db.execute(
                "SELECT COUNT(*) as pairs, AVG(score) as avg_score, MAX(updated_at) as last_retrain FROM item_similarities"
            )).fetchone()

        return {
            "total_clicks":    total_clicks,
            "total_sessions":  total_sessions,
            "total_items":     total_items,
            "items_with_recs": items_with_recs,
            "coverage":        round(items_with_recs / total_items, 4) if total_items else 0,
            "avg_score":       round(sim_row["avg_score"] or 0, 4),
            "total_pairs":     sim_row["pairs"] or 0,
            "last_retrain_ts": sim_row["last_retrain"],
        }

    @router.get("/clicks/top")
    async def top_items(limit: int = 20):
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row
            rows = await (await db.execute(
                """
                SELECT ce.item_id, i.name, i.category, COUNT(*) AS clicks
                FROM   click_events ce
                LEFT JOIN items i ON ce.item_id = i.item_id
                GROUP  BY ce.item_id
                ORDER  BY clicks DESC
                LIMIT  ?
                """,
                (limit,),
            )).fetchall()
        return {"items": [dict(r) for r in rows]}

    @router.get("/clicks/timeseries")
    async def clicks_timeseries(days: int = 14):
        cutoff_ms = int(
            (datetime.datetime.now() - datetime.timedelta(days=days)).timestamp() * 1000
        )
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row
            rows = await (await db.execute(
                """
                SELECT date(ts / 1000, 'unixepoch') AS day, COUNT(*) AS cnt
                FROM   click_events
                WHERE  ts >= ?
                GROUP  BY day
                ORDER  BY day ASC
                """,
                (cutoff_ms,),
            )).fetchall()

        today    = datetime.date.today()
        all_days = [(today - datetime.timedelta(days=days - 1 - i)).isoformat() for i in range(days)]
        day_map  = {r["day"]: r["cnt"] for r in rows}
        return {"days": all_days, "counts": [day_map.get(d, 0) for d in all_days]}

    @router.get("/matrix")
    async def coclick_matrix(limit: int = 20):
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row

            top_rows = await (await db.execute(
                "SELECT item_id FROM click_events GROUP BY item_id ORDER BY COUNT(*) DESC LIMIT ?",
                (limit,),
            )).fetchall()

            if not top_rows:
                return {"items": [], "labels": [], "matrix": []}

            top_ids = [r["item_id"] for r in top_rows]
            n       = len(top_ids)
            ph      = ",".join("?" * n)

            pair_rows = await (await db.execute(
                f"""
                SELECT a.item_id AS item_a, b.item_id AS item_b,
                       COUNT(DISTINCT a.session_id) AS cnt
                FROM   click_events a
                JOIN   click_events b
                       ON  a.session_id = b.session_id
                       AND a.item_id   != b.item_id
                WHERE  a.item_id IN ({ph})
                  AND  b.item_id IN ({ph})
                GROUP  BY a.item_id, b.item_id
                """,
                top_ids + top_ids,
            )).fetchall()

            name_rows = await (await db.execute(
                f"SELECT item_id, name FROM items WHERE item_id IN ({ph})",
                top_ids,
            )).fetchall()

        names  = {r["item_id"]: r["name"] for r in name_rows}
        idx    = {item_id: i for i, item_id in enumerate(top_ids)}
        matrix = [[0] * n for _ in range(n)]

        for row in pair_rows:
            matrix[idx[row["item_a"]]][idx[row["item_b"]]] = row["cnt"]

        return {
            "items":  top_ids,
            "labels": [names.get(i, i) for i in top_ids],
            "matrix": matrix,
        }

    @router.get("/export")
    async def export_recommendations():
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row

            item_rows = await (await db.execute(
                "SELECT item_id, name, category, price, image_url, in_stock FROM items ORDER BY category, name"
            )).fetchall()

            sim_rows = await (await db.execute(
                """
                SELECT s.item_id, s.similar_id, s.score,
                       i.name, i.category, i.price, i.image_url, i.in_stock
                FROM   item_similarities s
                LEFT JOIN items i ON s.similar_id = i.item_id
                ORDER  BY s.item_id, s.score DESC
                """
            )).fetchall()

        rec_map: dict[str, list[dict]] = {}
        for row in sim_rows:
            rec_map.setdefault(row["item_id"], []).append({
                "item_id":   row["similar_id"],
                "score":     row["score"],
                "name":      row["name"],
                "category":  row["category"],
                "price":     row["price"],
                "image_url": row["image_url"],
                "in_stock":  bool(row["in_stock"]),
            })

        payload = {
            "exported_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "items": [
                {
                    "item_id":        r["item_id"],
                    "name":           r["name"],
                    "category":       r["category"],
                    "price":          r["price"],
                    "image_url":      r["image_url"],
                    "in_stock":       bool(r["in_stock"]),
                    "recommendations": rec_map.get(r["item_id"], []),
                }
                for r in item_rows
            ],
        }

        return JSONResponse(
            content=payload,
            headers={"Content-Disposition": 'attachment; filename="recommendations.json"'},
        )

    @router.get("/export/csv")
    async def export_recommendations_csv():
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row
            sim_rows = await (await db.execute(
                """
                SELECT s.item_id,     ia.name AS item_name,     ia.category AS item_category,
                       s.similar_id,  ib.name AS rec_name,      ib.category AS rec_category,
                       s.score
                FROM   item_similarities s
                LEFT JOIN items ia ON s.item_id    = ia.item_id
                LEFT JOIN items ib ON s.similar_id = ib.item_id
                ORDER  BY s.item_id, s.score DESC
                """
            )).fetchall()

        buf = io.StringIO()
        writer = csv.writer(buf)
        writer.writerow(["item_id", "item_name", "item_category", "rec_item_id", "rec_name", "rec_category", "score"])
        for row in sim_rows:
            writer.writerow([
                row["item_id"], row["item_name"], row["item_category"],
                row["similar_id"], row["rec_name"], row["rec_category"],
                round(row["score"], 6),
            ])

        buf.seek(0)
        return StreamingResponse(
            iter([buf.getvalue()]),
            media_type="text/csv",
            headers={"Content-Disposition": 'attachment; filename="recommendations.csv"'},
        )

    return router
